<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/functions.php';require_login();$page_title='Categories';$error='';
if(isset($_GET['delete'])){try{$q=$pdo->prepare("DELETE FROM categories WHERE id=?");$q->execute([(int)$_GET['delete']]);flash('Category deleted.');}catch(PDOException $e){flash('Could not delete category.','danger');}header('Location: '.app_url('modules/categories/index.php'));exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['category_name']??'');$desc=trim($_POST['description']??'');if($name===''){$error='Category name is required.';}else{try{$q=$pdo->prepare("INSERT INTO categories(category_name,description) VALUES(?,?)");$q->execute([$name,$desc?:null]);flash('Category added.');header('Location: '.app_url('modules/categories/index.php'));exit;}catch(PDOException $e){$error='Category name already exists or could not be saved.';}}}
$rows=$pdo->query("SELECT c.*,COUNT(b.id) book_count FROM categories c LEFT JOIN books b ON b.category_id=c.id GROUP BY c.id ORDER BY c.category_name")->fetchAll();require __DIR__.'/../../includes/header.php';?>
<div class="row"><div class="col-md-4"><div class="card card-primary"><div class="card-header"><h3 class="card-title">Add Category</h3></div><form method="post"><div class="card-body"><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-group"><label>Category Name *</label><input class="form-control" name="category_name" required></div><div class="form-group"><label>Description</label><textarea class="form-control" name="description"></textarea></div></div><div class="card-footer"><button class="btn btn-primary">Save Category</button></div></form></div></div>
<div class="col-md-8"><div class="card"><div class="card-header"><h3 class="card-title">Category List</h3></div><div class="card-body table-responsive"><table class="table table-bordered"><thead><tr><th>ID</th><th>Category</th><th>Description</th><th>Books</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= (int)$r['id']?></td><td><?=e($r['category_name'])?></td><td><?=e($r['description'])?></td><td><?= (int)$r['book_count']?></td><td><a class="btn btn-danger btn-sm" onclick="return confirm('Delete this category? Books will remain but become uncategorized.')" href="?delete=<?=(int)$r['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require __DIR__.'/../../includes/footer.php';?>
